{"cmd":"cd /testbed && PYTHONPATH=src python3 - << 'EOF'
import hashlib, hmac, json
from payhook.errors import InvalidNotification
from payhook.receiver import parse_payment

SECRET = b"legacy-relay-secret"
NOW = 1760000000
stamp = str(NOW)

def r0(event_id):
    return "r0=" + hmac.new(SECRET, stamp.encode() + b"." + event_id.encode("utf-8"), hashlib.sha256).hexdigest()

def v1(body):
    return "v1=" + hmac.new(SECRET, stamp.encode() + b"." + body, hashlib.sha256).hexdigest()

event = {"event_id": "evt-r0", "account_id": "acct-客户", "amount_minor": 0, "currency": "EUR"}

# 1. v0: reformatted body (reserialized), no v1, valid r0 -> accept
body = json.dumps(event, ensure_ascii=False, indent=2, sort_keys=True).encode()
res = parse_payment(body, {"X-Pay-Timestamp": stamp, "X-Pay-Receipt": r0("evt-r0")}, SECRET, NOW)
assert res == event, res

# 2. v0: v1 present but does not match (body rewritten), valid r0 -> accept
res = parse_payment(body, {"X-Pay-Timestamp": stamp, "X-Pay-Signature": v1(b"old-body"), "X-Pay-Receipt": r0("evt-r0")}, SECRET, NOW)
assert res == event, res

# 3. bad r0 -> reject
try:
    parse_payment(body, {"X-Pay-Timestamp": stamp, "X-Pay-Receipt": "r0=" + "0" * 64}, SECRET, NOW)
    raise SystemExit("FAIL: bad r0 accepted")
except InvalidNotification:
    pass

# 4. r0 over wrong event_id -> reject
try:
    parse_payment(body, {"X-Pay-Timestamp": stamp, "X-Pay-Receipt": r0("evt-other")}, SECRET, NOW)
    raise SystemExit("FAIL: wrong-event r0 accepted")
except InvalidNotification:
    pass

# 5. valid r0 but stale timestamp -> reject
try:
    parse_payment(body, {"X-Pay-Timestamp": stamp, "X-Pay-Receipt": r0("evt-r0")}, SECRET, NOW + 301)
    raise SystemExit("FAIL: stale r0 accepted")
except InvalidNotification:
    pass

# 6. v1 still wins/intact on canonical body
canon = json.dumps(event, ensure_ascii=False).encode()
res = parse_payment(canon, {"X-Pay-Timestamp": stamp, "X-Pay-Signature": v1(canon)}, SECRET, NOW)
assert res == event, res

# 7. field validation: bool amount, negative, bad currency, non-dict, malformed JSON
for bad in [dict(event, amount_minor=True), dict(event, amount_minor=-1), dict(event, currency="usd"),
            dict(event, currency="US"), dict(event, event_id=""), dict(event, account_id=7)]:
    b = json.dumps(bad).encode()
    try:
        parse_payment(b, {"X-Pay-Timestamp": stamp, "X-Pay-Signature": v1(b)}, SECRET, NOW)
        raise SystemExit(f"FAIL: bad fields accepted: {bad}")
    except InvalidNotification:
        pass
for raw in [b"[1,2]", b"not json", b'{"event_id": 1}']:
    try:
        parse_payment(raw, {"X-Pay-Timestamp": stamp, "X-Pay-Signature": v1(raw)}, SECRET, NOW)
        raise SystemExit(f"FAIL: bad body accepted: {raw}")
    except InvalidNotification:
        pass

# 8. missing timestamp, malformed timestamp, boundary window (exactly 300s) 
try:
    parse_payment(canon, {"X-Pay-Signature": v1(canon)}, SECRET, NOW)
    raise SystemExit("FAIL: missing timestamp accepted")
except InvalidNotification:
    pass
try:
    parse_payment(canon, {"X-Pay-Timestamp": "1.5", "X-Pay-Signature": v1(canon)}, SECRET, NOW)
    raise SystemExit("FAIL: malformed timestamp accepted")
except InvalidNotification:
    pass
edge = str(NOW - 300)
d = "v1=" + hmac.new(SECRET, edge.encode() + b"." + canon, hashlib.sha256).hexdigest()
assert parse_payment(canon, {"X-Pay-Timestamp": edge, "X-Pay-Signature": d}, SECRET, NOW) == event

print("all r0/edge manual checks passed")
EOF"}
